import{_ as t,o as n,c as o,a2 as r}from"./chunks/framework.BXA5Pi9t.js";const d=JSON.parse('{"title":"CDS Hammer (Day 2) - OSD (Tiering): Fine-Grained Promotion Unit","description":"","frontmatter":{"title":"CDS Hammer (Day 2) - OSD (Tiering): Fine-Grained Promotion Unit","date":"2014-10-30T00:00:00.000Z","updated":"2014-10-30T00:00:00.000Z","tags":["Ceph","Distributed Storage","OSD Tiering","Fine","Grained Promotion","Performance Optimization"],"categories":["会议纪要","存储技术"],"outline":"deep"},"headers":[],"relativePath":"posts/2014/CDS_Hammer_Day_2_-_OSD_Tiering_-_Fine-Grained_Promotion_Unit.md","filePath":"posts/2014/CDS_Hammer_Day_2_-_OSD_Tiering_-_Fine-Grained_Promotion_Unit.md","lastUpdated":1780459816000}'),e={name:"posts/2014/CDS_Hammer_Day_2_-_OSD_Tiering_-_Fine-Grained_Promotion_Unit.md"};function l(s,i,a,_,p,g){return n(),o("div",null,[...i[0]||(i[0]=[r('<h3 id="会议纪要" tabindex="-1">会议纪要 <a class="header-anchor" href="#会议纪要" aria-label="Permalink to &quot;会议纪要&quot;">​</a></h3><p><strong>会议主题</strong>： Ceph存储系统中OSD分层策略优化——细粒度提升单元</p><p><strong>会议时间</strong>： 2023年11月（具体日期未提及）</p><p><strong>参会人员</strong>： 未知</p><p><strong>会议内容</strong>：</p><p><strong>一、背景及议题</strong></p><p>本次会议重点讨论了Ceph存储系统中OSD分层策略的优化，特别是针对细粒度提升单元（fine grain promotion units）的探讨。会议分析了现有分层策略的优缺点，并探讨了改进方案。</p><p><strong>二、主要议题</strong></p><ol><li><p><strong>现有分层策略分析</strong>：</p><ul><li>会议分析了不同分层策略（如全闪存、混合分层、无分层）在随机读和写操作中的性能表现。</li><li>指出当前分层策略在处理随机分布的数据时，由于缓存过小，导致缓存命中率低，从而影响性能。</li></ul></li><li><p><strong>细粒度提升单元</strong>：</p><ul><li>讨论了使用细粒度提升单元（如4K页）进行提升的可行性。</li><li>指出细粒度提升单元可以提高缓存命中率，但同时也增加了复杂性，特别是在与快照交互时。</li></ul></li><li><p><strong>优化方案</strong>：</p><ul><li><strong>改进提升策略</strong>： 在提升过程中，将读取操作转发到后端存储，避免读取操作阻塞提升过程。提升操作完成后，将读取操作代理到提升后的数据，进一步提高性能。</li><li><strong>优化提升单元粒度</strong>： 使用更小的提升单元（如4K页）进行提升，提高缓存命中率。但需注意，细粒度提升单元会增加复杂性，尤其是在与快照交互时。</li></ul></li></ol><p><strong>三、行动方案</strong></p><ol><li><p><strong>短期</strong>：</p><ul><li>优化提升策略，将读取操作转发到后端存储，避免读取操作阻塞提升过程。</li><li>研究代理读取操作的可能性，进一步提高性能。</li></ul></li><li><p><strong>中期</strong>：</p><ul><li>评估细粒度提升单元的可行性，并研究其在与快照交互时的复杂性。</li><li>研究使用更小的提升单元进行提升的方案。</li></ul></li><li><p><strong>长期</strong>：</p><ul><li>优化Ceph存储系统中的OSD分层策略，提高系统整体性能。</li></ul></li></ol><p><strong>四、其他</strong></p><ul><li>会议指出，当前分层策略在处理随机分布的数据时，可能导致性能下降。</li><li>讨论了使用细粒度提升单元进行提升的可行性，并探讨了改进方案。</li><li>提出了短期、中期和长期行动方案，以优化Ceph存储系统中的OSD分层策略。</li></ul>',13)])])}const D=t(e,[["render",l]]);export{d as __pageData,D as default};
